#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp> // for noarr::serialize_data

#include "defines.hpp"
#include "deriche.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// img[i][j] with j the innermost (contiguous) dimension, as in C (img[W][H])
	DEFINE_PROTO_STRUCT(img_layout, j_vec ^ i_vec);
} tuning;

// initialization function
// imgIn, imgOut: i x j
void init_array(num_t &alpha, auto imgIn, auto imgOut) {
	using namespace noarr;
	(void)imgOut; // not used, kept for interface similarity

	alpha = SCALAR_VAL(0.25); // parameter of the filter

	// input should be between 0 and 1 (grayscale image pixel)
	// Parallel over rows (dimension 'i'); each thread initializes full rows independently.
	auto trav = traverser(imgIn);
	auto row_range = trav.template range<'i'>();

#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
	for (std::size_t r = 0; r < row_range.size(); ++r) {
		auto inner = row_range[r]; // 'i' fixed, 'j' free

		inner.for_each([&](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			// arithmetic kept identical to original; only loop structure changed
			imgIn[state] = (num_t)(((313 * i + 991 * j) % 65536) / 65535.0f);
		});
	}
}

// computation kernel
// imgIn, imgOut, y1, y2: i x j
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	// Precompute coefficients.
	// We preserve the original mathematical expression but avoid redundant
	// calls to EXP_FUN and POW_FUN by reusing common sub-expressions.
	const num_t one = SCALAR_VAL(1.0);
	const num_t two = SCALAR_VAL(2.0);

	const num_t ea  = EXP_FUN(-alpha);                 // exp(-alpha)
	const num_t e2a = EXP_FUN(SCALAR_VAL(-2.0) * alpha); // exp(-2*alpha)

	num_t k = (one - ea) * (one - ea) /
	          (one + two * alpha * ea - e2a);

	const num_t a1 = k;
	const num_t a2 = k * ea * (alpha - one);
	const num_t a3 = k * ea * (alpha + one);
	const num_t a4 = -k * e2a;

	// vertical coefficients identical to horizontal
	const num_t a5 = a1;
	const num_t a6 = a2;
	const num_t a7 = a3;
	const num_t a8 = a4;

	const num_t b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	const num_t b2 = -e2a;
	const num_t c1 = one;
	const num_t c2 = one;

	// lengths used for reverse traversals
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

#pragma scop
	// 1st pass: causal filter along j, for each i (forward j)
	// for (i=0; i<W; i++)
	//   ym1=0; ym2=0; xm1=0;
	//   for (j=0; j<H; j++)
	//     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2; ...
	{
		auto trav = traverser(y1, imgIn);
		auto row_range = trav.template range<'i'>();

#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
		for (std::size_t r = 0; r < row_range.size(); ++r) {
			auto inner = row_range[r]; // 'i' fixed, iterate over 'j'

			num_t ym1 = SCALAR_VAL(0.0);
			num_t ym2 = SCALAR_VAL(0.0);
			num_t xm1 = SCALAR_VAL(0.0);

			inner.for_each([&](auto state) {
				const num_t x = imgIn[state];
				const num_t y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

				y1[state] = y;

				xm1 = x;
				ym2 = ym1;
				ym1 = y;
			});
		}
	}

	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	// Original C: j from H-1 down to 0
	// Here we traverse j in 0..H-1 and map r -> j = H-1-r
	{
		auto trav = traverser(y2, imgIn);
		auto row_range = trav.template range<'i'>();

#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
		for (std::size_t r = 0; r < row_range.size(); ++r) {
			auto inner = row_range[r]; // 'i' fixed, iterate over 'j' (reversed mapping)

			num_t yp1 = SCALAR_VAL(0.0);
			num_t yp2 = SCALAR_VAL(0.0);
			num_t xp1 = SCALAR_VAL(0.0);
			num_t xp2 = SCALAR_VAL(0.0);

			inner.for_each([&](auto state) {
				auto [i_idx, r_j] = get_indices<'i', 'j'>(state);
				const std::size_t j_idx = h_len - 1 - r_j;
				auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

				const num_t y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
				y2[rev_state] = y;

				const num_t x = imgIn[rev_state];

				xp2 = xp1;
				xp1 = x;
				yp2 = yp1;
				yp1 = y;
			});
		}
	}

	// Combine vertical passes
	// imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	{
		auto trav = traverser(imgOut, y1, y2);
		auto row_range = trav.template range<'i'>();

#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
		for (std::size_t r = 0; r < row_range.size(); ++r) {
			auto inner = row_range[r]; // 'i' fixed, iterate over 'j'

			inner.for_each([&](auto state) {
				imgOut[state] = c1 * (y1[state] + y2[state]);
			});
		}
	}

	// 3rd pass: causal filter along i, for each j (forward i)
	// for (j=0; j<H; j++)
	//   tm1=0; ym1=0; ym2=0;
	//   for (i=0; i<W; i++)
	//     y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2; ...
	{
		auto trav = traverser(y1, imgOut);
		auto col_range = trav.template range<'j'>();

#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
		for (std::size_t c = 0; c < col_range.size(); ++c) {
			auto inner = col_range[c]; // 'j' fixed, iterate over 'i'

			num_t tm1 = SCALAR_VAL(0.0);
			num_t ym1 = SCALAR_VAL(0.0);
			num_t ym2 = SCALAR_VAL(0.0);

			inner.for_each([&](auto state) {
				const num_t x = imgOut[state];
				const num_t y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

				y1[state] = y;

				tm1 = x;
				ym2 = ym1;
				ym1 = y;
			});
		}
	}

	// 4th pass: anti-causal filter along i, for each j (reverse i)
	// Original C: i from W-1 down to 0
	// Here we traverse i in 0..W-1 and map r -> i = W-1-r
	{
		auto trav = traverser(y2, imgOut);
		auto col_range = trav.template range<'j'>();

#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
		for (std::size_t c = 0; c < col_range.size(); ++c) {
			auto inner = col_range[c]; // 'j' fixed, iterate over 'i' (reversed mapping)

			num_t tp1 = SCALAR_VAL(0.0);
			num_t tp2 = SCALAR_VAL(0.0);
			num_t yp1 = SCALAR_VAL(0.0);
			num_t yp2 = SCALAR_VAL(0.0);

			inner.for_each([&](auto state) {
				auto [r_i, j_idx] = get_indices<'i', 'j'>(state);
				const std::size_t i_idx = w_len - 1 - r_i;
				auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

				const num_t y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
				y2[rev_state] = y;

				const num_t x = imgOut[rev_state];

				tp2 = tp1;
				tp1 = x;
				yp2 = yp1;
				yp1 = y;
			});
		}
	}

	// Final combine
	// imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	{
		auto trav = traverser(imgOut, y1, y2);
		auto row_range = trav.template range<'i'>();

#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
		for (std::size_t r = 0; r < row_range.size(); ++r) {
			auto inner = row_range[r]; // 'i' fixed, iterate over 'j'

			inner.for_each([&](auto state) {
				imgOut[state] = c2 * (y1[state] + y2[state]);
			});
		}
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

	// images: i x j
	auto imgIn  = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto imgOut = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y1     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y2     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);

	// initialize data
	init_array(alpha, imgIn.get_ref(), imgOut.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_deriche(alpha, imgIn.get_ref(), imgOut.get_ref(), y1.get_ref(), y2.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE prevention)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, imgOut.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
