// computation kernel
// imgIn, imgOut, y1, y2: i x j
//
// Optimized version:
// - Factor the 1D Deriche pass along the contiguous 'j' dimension into a local
//   lambda (deriche_1d_j).
// - Reuse this 1D pass for both the horizontal and vertical stages.
//   The vertical stage is implemented by working on a *transposed view*
//   (dimensions 'i' and 'j' renamed) so that the filtered dimension is again
//   contiguous in memory, without actually moving data.
// - Reverse passes are implemented by walking 'j' forward while keeping our
//   own decreasing index; this avoids recomputing indices from the traverser
//   state every iteration and keeps accesses linear in memory.
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// coefficient setup (unchanged from C version)
	k = (SCALAR_VAL(1.0) - EXP_FUN(-alpha)) *
	    (SCALAR_VAL(1.0) - EXP_FUN(-alpha)) /
	    (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * EXP_FUN(-alpha) - EXP_FUN(SCALAR_VAL(2.0) * alpha));
	a1 = a5 = k;
	a2 = a6 = k * EXP_FUN(-alpha) * (alpha - SCALAR_VAL(1.0));
	a3 = a7 = k * EXP_FUN(-alpha) * (alpha + SCALAR_VAL(1.0));
	a4 = a8 = -k * EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	b2 = -EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	c1 = c2 = SCALAR_VAL(1.0);

	// Generic 1D Deriche pass along the contiguous 'j' dimension.
	//
	// For a structure src[i][j] (with 'j' contiguous), this performs:
	//   1) causal filter along 'j' for each fixed 'i'  (forward j)
	//   2) anti-causal filter along 'j' for each fixed 'i' (reverse j)
	//   3) combination  dst = c * (y_fwd + y_bwd)
	//
	// The same code is used for:
	//   - horizontal stage: src = imgIn,  dst = imgOut
	//   - vertical  stage: src = imgOut^T, dst = imgOut^T
	//
	// The vertical stage is done on a transposed *view* created using
	// noarr::rename<'i','j','j','i'>(), so that the column-wise filter along
	// original 'i' becomes a row-wise filter along the contiguous 'j' of the
	// transposed view. This improves locality without moving data.
	auto deriche_1d_j = [&](auto src, auto dst, auto tmp_fwd, auto tmp_bwd,
	                        num_t a_fwd1, num_t a_fwd2,
	                        num_t a_bwd1, num_t a_bwd2,
	                        num_t b_coef1, num_t b_coef2,
	                        num_t c_coef) {
		// length of the filtered (inner) dimension
		const std::size_t len_j = src | get_length<'j'>();

		// 1st pass: causal filter along j, for each i (forward j)
		// for (i=0; i<W; i++)
		//   ym1=0; ym2=0; xm1=0;
		//   for (j=0; j<H; j++)
		//     y1[i][j] = a_fwd1*src[i][j] + a_fwd2*xm1 + b1*ym1 + b2*ym2; ...
		traverser(tmp_fwd, src).template for_dims<'i'>([&](auto row_trav) {
			num_t ym1 = SCALAR_VAL(0.0);
			num_t ym2 = SCALAR_VAL(0.0);
			num_t xm1 = SCALAR_VAL(0.0);

			row_trav.for_each([&](auto state) {
				const num_t x = src[state];
				const num_t y = a_fwd1 * x
				              + a_fwd2 * xm1
				              + b_coef1 * ym1
				              + b_coef2 * ym2;

				tmp_fwd[state] = y;

				xm1 = x;
				ym2 = ym1;
				ym1 = y;
			});
		});

		// 2nd pass: anti-causal filter along j, for each i (reverse j)
		// Original C: j from H-1 down to 0.
		// Here we iterate j forward (0..H-1) but keep our own decreasing index
		// j_rev = H-1, H-2, ..., 0 and build the appropriate state for that.
		traverser(tmp_bwd, src).template for_dims<'i'>([&](auto row_trav) {
			num_t yp1 = SCALAR_VAL(0.0);
			num_t yp2 = SCALAR_VAL(0.0);
			num_t xp1 = SCALAR_VAL(0.0);
			num_t xp2 = SCALAR_VAL(0.0);

			// Fixed index in 'i' for this row
			auto base_state = row_trav.state(); // contains index_in<'i'>
			std::size_t j_rev = len_j;          // will be pre-decremented in the loop

			row_trav.for_each([&](auto /*unused*/) {
				--j_rev; // goes len_j-1, len_j-2, ..., 0
				auto rev_state = base_state + idx<'j'>(j_rev);

				// y_tmp = a_bwd1 * x[n+1] + a_bwd2 * x[n+2]
				//        + b1 * y[n+1]   + b2 * y[n+2]
				const num_t y = a_bwd1 * xp1
				              + a_bwd2 * xp2
				              + b_coef1 * yp1
				              + b_coef2 * yp2;

				tmp_bwd[rev_state] = y;

				// Shift the history
				xp2 = xp1;
				xp1 = src[rev_state];
				yp2 = yp1;
				yp1 = y;
			});
		});

		// Combine both passes
		// dst[i][j] = c * (tmp_fwd[i][j] + tmp_bwd[i][j]);
		traverser(dst, tmp_fwd, tmp_bwd).for_each([&](auto state) {
			dst[state] = c_coef * (tmp_fwd[state] + tmp_bwd[state]);
		});
	};

	// ------------------------------------------------------------------
	// Horizontal stage: filter along j for each i  (rows).
	// Uses imgIn as input, imgOut as output, y1/y2 as temporaries.
	// ------------------------------------------------------------------
	deriche_1d_j(imgIn, imgOut, y1, y2,
	             a1, a2,  // causal coeffs
	             a3, a4,  // anti-causal coeffs
	             b1, b2,
	             c1);

	// ------------------------------------------------------------------
	// Vertical stage: filter along i for each j (columns).
	//
	// Implemented as the same 1D filter along j on a *transposed view*:
	//   imgOut_T[i_T][j_T] = imgOut[j_T][i_T]
	//   y1_T, y2_T similar
	//
	// Each original column j becomes a row i_T in the transposed view, and
	// each original i becomes j_T. Running the same 1D Deriche pass along
	// j_T in the transposed view is therefore equivalent to filtering along
	// the original i dimension, but now the traversed dimension is again
	// contiguous in memory, which greatly improves cache behavior.
	// ------------------------------------------------------------------
	auto imgOut_T = imgOut ^ rename<'i', 'j', 'j', 'i'>();
	auto y1_T     = y1     ^ rename<'i', 'j', 'j', 'i'>();
	auto y2_T     = y2     ^ rename<'i', 'j', 'j', 'i'>();

	deriche_1d_j(imgOut_T, imgOut_T, y1_T, y2_T,
	             a5, a6,  // causal coeffs for vertical pass
	             a7, a8,  // anti-causal coeffs for vertical pass
	             b1, b2,
	             c2);
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

	// images: i x j
	auto imgIn  = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto imgOut = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y1     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y2     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);

	// initialize data
	init_array(alpha, imgIn.get_ref(), imgOut.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_deriche(alpha, imgIn.get_ref(), imgOut.get_ref(), y1.get_ref(), y2.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE prevention)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, imgOut.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
