	a2 = a6 = k * EXP_FUN(-alpha) * (alpha - SCALAR_VAL(1.0));
	a3 = a7 = k * EXP_FUN(-alpha) * (alpha + SCALAR_VAL(1.0));
	a4 = a8 = -k * EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	b2 = -EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	c1 = c2 = SCALAR_VAL(1.0);

	// lengths used for reverse traversals
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

	// --------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//
	// for (i=0; i<W; i++)
	//   ym1=0; ym2=0; xm1=0;
	//   for (j=0; j<H; j++)
	//     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2; ...
	//
	// We parallelize over rows (dimension 'i'): each row is independent.
	// Within a row, we iterate j in increasing order, which matches the
	// contiguous memory layout and maximizes cache efficiency.
	// --------------------------------------------------------------------
	{
		auto row_trav = traverser(y1, imgIn);

		#pragma omp parallel for schedule(static)
		for (auto row : row_trav) { // each 'row' has fixed 'i', iterates over 'j'
			num_t ym1 = SCALAR_VAL(0.0);
			num_t ym2 = SCALAR_VAL(0.0);
			num_t xm1 = SCALAR_VAL(0.0);

			row.for_each([&](auto state) {
				// One address computation per bag per element
				auto &in_ij  = imgIn[state];
				auto &y1_ij  = y1[state];

				y1_ij = a1 * in_ij + a2 * xm1 + b1 * ym1 + b2 * ym2;
				xm1   = in_ij;
				ym2   = ym1;
				ym1   = y1_ij;
			});
		}
	}

	// --------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	//
	// Original C:
	// for (i=0; i<W; i++)
	//   yp1=0; yp2=0; xp1=0; xp2=0;
	//   for (j=H-1; j>=0; j--)
	//     y2[i][j] = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2; ...
	//
	// We still traverse j in 0..H-1 via the traverser, but we maintain a
	// separate "reverse" state that walks j from H-1 down to 0. That way we
	// avoid per-iteration recomputation of (H-1-j) and only update a state
	// with simple arithmetic:
	//   rev_state = rev_state - idx<'j'>(1);
	// --------------------------------------------------------------------
	{
		auto row_trav = traverser(y2, imgIn);

		#pragma omp parallel for schedule(static)
		for (auto row : row_trav) { // independent rows
			num_t yp1 = SCALAR_VAL(0.0);
			num_t yp2 = SCALAR_VAL(0.0);
			num_t xp1 = SCALAR_VAL(0.0);
			num_t xp2 = SCALAR_VAL(0.0);

			// Starting state: (i fixed, j = h_len-1)
			auto base_state = row.state(); // contains 'i'
			auto rev_state  = base_state + idx<'j'>(h_len - 1);

			row.for_each([&](auto /*forward_state*/) {
				// Work on the reverse element addressed by rev_state
				auto &in_rev = imgIn[rev_state];
				auto &y2_rev = y2[rev_state];

				y2_rev = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
				xp2    = xp1;
				xp1    = in_rev;
				yp2    = yp1;
				yp1    = y2_rev;

				// Move one step backwards in j; the very last decrement
				// produces an unused state, which is fine.
				rev_state = rev_state - idx<'j'>(1);
			});
		}
	}

	// --------------------------------------------------------------------
	// Combine vertical passes:
	//   imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	//
	// Pointwise, embarrassingly parallel and cache-friendly (j innermost).
	// --------------------------------------------------------------------
	{
		auto row_trav = traverser(imgOut, y1, y2);

		#pragma omp parallel for schedule(static)
		for (auto row : row_trav) {
			row.for_each([&](auto state) {
				const num_t v1 = y1[state];
				const num_t v2 = y2[state];
				imgOut[state]  = c1 * (v1 + v2);
			});
		}
	}

	// --------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//
	// for (j=0; j<H; j++)
	//   tm1=0; ym1=0; ym2=0;
	//   for (i=0; i<W; i++)
	//     y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2; ...
	//
	// Here, recurrences are column-wise. We therefore hoist 'j' as the
	// outermost dimension and parallelize over columns. Within each column,
	// i runs from 0..W-1, which is strided in memory but required by the
	// algorithm. Each column is independent and gets its own tm1/ym1/ym2.
	// --------------------------------------------------------------------
	{
		auto col_trav = traverser(y1, imgOut).order(hoist<'j'>());

		#pragma omp parallel for schedule(static)
		for (auto col : col_trav) { // each 'col' has fixed 'j', iterates over 'i'
			num_t tm1 = SCALAR_VAL(0.0);
			num_t ym1 = SCALAR_VAL(0.0);
			num_t ym2 = SCALAR_VAL(0.0);

			col.for_each([&](auto state) {
				auto &out_ij = imgOut[state];
				auto &y1_ij  = y1[state];

				y1_ij = a5 * out_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;
				tm1   = out_ij;
				ym2   = ym1;
				ym1   = y1_ij;
			});
		}
	}

	// --------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	//
	// Original C:
	// for (j=0; j<H; j++)
	//   tp1=0; tp2=0; yp1=0; yp2=0;
	//   for (i=W-1; i>=0; i--)
	//     y2[i][j] = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2; ...
	//
	// As in the 2nd pass, we iterate i forward (0..W-1) via the traverser,
	// but maintain a reverse state that walks i from W-1 down to 0. Each
	// column is again independent and gets private accumulators.
	// --------------------------------------------------------------------
	{
		auto col_trav = traverser(y2, imgOut).order(hoist<'j'>());

		#pragma omp parallel for schedule(static)
		for (auto col : col_trav) {
			num_t tp1 = SCALAR_VAL(0.0);
			num_t tp2 = SCALAR_VAL(0.0);
			num_t yp1 = SCALAR_VAL(0.0);
			num_t yp2 = SCALAR_VAL(0.0);

			// Starting reverse state: (i = w_len-1, current column j)
			auto base_state = col.state(); // contains 'j'
			auto rev_state  = base_state + idx<'i'>(w_len - 1);

			col.for_each([&](auto /*forward_state*/) {
				auto &out_rev = imgOut[rev_state];
				auto &y2_rev  = y2[rev_state];

				y2_rev = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
				tp2    = tp1;
				tp1    = out_rev;
				yp2    = yp1;
				yp1    = y2_rev;

				// Step one element up in i; last decrement yields an
				// unused state, which is fine.
				rev_state = rev_state - idx<'i'>(1);
			});
		}
	}

	// --------------------------------------------------------------------
	// Final combine:
	//   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	//
	// Again pointwise and parallelizable over rows.
	// --------------------------------------------------------------------
	{
		auto row_trav = traverser(imgOut, y1, y2);

		#pragma omp parallel for schedule(static)
		for (auto row : row_trav) {
			row.for_each([&](auto state) {
				const num_t v1 = y1[state];
				const num_t v2 = y2[state];
				imgOut[state]  = c2 * (v1 + v2);
			});
		}
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

	// images: i x j
	auto imgIn  = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto imgOut = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y1     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y2     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);

	// initialize data
	init_array(alpha, imgIn.get_ref(), imgOut.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_deriche(alpha, imgIn.get_ref(), imgOut.get_ref(), y1.get_ref(), y2.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE prevention)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, imgOut.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
