// computation kernel
// imgIn, imgOut, y1, y2: i x j
// The original Polybench kernel uses four global 2D temporaries (y1,y2 twice).
// Here we keep the same external interface, but:
//  - fuse each pair of vertical/horizontal passes,
//  - and implement them using per-column / per-row 1D temporary buffers.
//
// This greatly reduces global memory traffic while preserving exact arithmetic.
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// ---------------------------------------------------------------------
	// Coefficient setup (unchanged numerically, but common subexpressions
	// are hoisted so that EXP_FUN / POW_FUN are called only a few times).
	// ---------------------------------------------------------------------
	const num_t one = SCALAR_VAL(1.0);
	const num_t two = SCALAR_VAL(2.0);

	const num_t exp_m_alpha  = EXP_FUN(-alpha);
	const num_t exp_p_2alpha = EXP_FUN(two * alpha);
	const num_t exp_m_2alpha = EXP_FUN(-two * alpha);
	const num_t pow_2_m_alpha = POW_FUN(two, -alpha);

	k  = (one - exp_m_alpha) * (one - exp_m_alpha)
	    / (one + two * alpha * exp_m_alpha - exp_p_2alpha);
	a1 = a5 = k;
	a2 = a6 = k * exp_m_alpha * (alpha - one);
	a3 = a7 = k * exp_m_alpha * (alpha + one);
	a4 = a8 = -k * exp_m_2alpha;
	b1 = pow_2_m_alpha;
	b2 = -exp_m_2alpha;
	c1 = c2 = one;

	// lengths (used for reverse traversals and 1D work buffers)
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

	// ---------------------------------------------------------------------
	// Vertical stage: 1st + 2nd pass along j, then combine into imgOut.
	//
	// Original C code:
	//  1) forward causal along j into y1
	//  2) backward anti-causal along j into y2
	//  3) imgOut = c1 * (y1 + y2)
	//
	// We implement the same recurrences, but for each column i we use
	// two 1D buffers y1_col[j], y2_col[j] instead of full 2D y1,y2.
	// This avoids two full-image reads/writes to y1/y2 in this stage.
	// ---------------------------------------------------------------------
	std::vector<num_t> y1_col(h_len);
	std::vector<num_t> y2_col(h_len);

	traverser(imgIn, imgOut).template for_dims<'i'>([&](auto inner) {
		// inner has 'i' fixed, will iterate 'j'
		const auto base_i_state = inner.state();
		const std::size_t i_idx = get_index<'i'>(base_i_state);

		// 1st pass: causal filter along j (forward j) into y1_col
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);
		num_t xm1 = SCALAR_VAL(0.0);

		inner.template for_each<'j'>([&](auto state) {
			const std::size_t j = get_index<'j'>(state);
			const num_t x = imgIn[state];

			const num_t y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;
			y1_col[j] = y;

			xm1 = x;
			ym2 = ym1;
			ym1 = y;
		});

		// 2nd pass: anti-causal filter along j (reverse j) into y2_col
		//
		// Original C loops j = H-1 .. 0. Here we iterate r_j = 0 .. H-1
		// and map to j = H-1-r_j to keep traversal forward while accessing
		// the correct column element in reverse order.
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

		inner.template for_each<'j'>([&](auto state) {
			const std::size_t r_j = get_index<'j'>(state);
			const std::size_t j   = h_len - 1 - r_j;

			const num_t y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
			y2_col[j] = y;

			const auto rev_state = base_i_state + idx<'j'>(j);
			const num_t x = imgIn[rev_state];

			xp2 = xp1;
			xp1 = x;
			yp2 = yp1;
			yp1 = y;
		});

		// Combine vertical passes into imgOut for this column:
		// imgOut[i][j] = c1 * (y1[i][j] + y2[i][j])
		inner.template for_each<'j'>([&](auto state) {
			const std::size_t j = get_index<'j'>(state);
			imgOut[state] = c1 * (y1_col[j] + y2_col[j]);
		});
	});

	// ---------------------------------------------------------------------
	// Horizontal stage: 3rd + 4th pass along i, then final combine.
	//
	// Original C code:
	//  3rd pass: causal filter along i into y1
	//  4th pass: anti-causal filter along i into y2
	//  final    : imgOut = c2 * (y1 + y2)
	//
	// Again we avoid full 2D y1,y2 here by using per-row 1D buffers
	// y1_row[i], y2_row[i]. We *do not* touch imgOut until both passes
	// for a given row j are complete, so the arithmetic matches exactly.
	// ---------------------------------------------------------------------
	std::vector<num_t> y1_row(w_len);
	std::vector<num_t> y2_row(w_len);

	traverser(imgOut).template for_dims<'j'>([&](auto inner) {
		// inner has 'j' fixed, will iterate 'i'
		const auto base_j_state = inner.state();
		const std::size_t j_idx = get_index<'j'>(base_j_state);

		// 3rd pass: causal filter along i (forward i) into y1_row
		num_t tm1 = SCALAR_VAL(0.0);
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);

		inner.template for_each<'i'>([&](auto state) {
			const std::size_t i = get_index<'i'>(state);
			const num_t x = imgOut[state];

			const num_t y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;
			y1_row[i] = y;

			tm1 = x;
			ym2 = ym1;
			ym1 = y;
		});

		// 4th pass: anti-causal filter along i (reverse i) into y2_row
		num_t tp1 = SCALAR_VAL(0.0);
		num_t tp2 = SCALAR_VAL(0.0);
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);

		inner.template for_each<'i'>([&](auto state) {
			const std::size_t r_i = get_index<'i'>(state);
			const std::size_t i   = w_len - 1 - r_i;

			const num_t y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
			y2_row[i] = y;

			const auto rev_state = idx<'i', 'j'>(i, j_idx);
			const num_t x = imgOut[rev_state];

			tp2 = tp1;
			tp1 = x;
			yp2 = yp1;
			yp1 = y;
		});

		// Final horizontal combine for this row:
		// imgOut[i][j] = c2 * (y1[i][j] + y2[i][j])
		inner.template for_each<'i'>([&](auto state) {
			const std::size_t i = get_index<'i'>(state);
			imgOut[state] = c2 * (y1_row[i] + y2_row[i]);
		});
	});

