	const std::size_t h_len = imgIn | get_length<'j'>(); // number of cols

	// ------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//
	// Original C:
	// for (i=0; i<W; i++) {
	//   ym1=0; ym2=0; xm1=0;
	//   for (j=0; j<H; j++) {
	//     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2;
	//     xm1 = imgIn[i][j];
	//     ym2 = ym1;
	//     ym1 = y1[i][j];
	//   }
	// }
	//
	// We parallelize over independent rows (dimension 'i'), while keeping
	// each inner recurrence over 'j' strictly sequential.
	// ------------------------------------------------------------------

	auto trav_rows_1 = traverser(y1, imgIn).order(hoist<'i'>());

#pragma omp parallel for schedule(static)
	for (auto inner : trav_rows_1) {
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);
		num_t xm1 = SCALAR_VAL(0.0);

		inner.template for_each<'j'>([&](auto state) {
			const num_t in_val  = imgIn[state];
			const num_t y1_val  = a1 * in_val + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y1_val;

			xm1 = in_val;
			ym2 = ym1;
			ym1 = y1_val;
		});
	}

	// ------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	//
	// Original C:
	// for (i=0; i<W; i++) {
	//   yp1=0; yp2=0; xp1=0; xp2=0;
	//   for (j=H-1; j>=0; j--) {
	//     y2[i][j] = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2;
	//     xp2 = xp1; xp1 = imgIn[i][j];
	//     yp2 = yp1; yp1 = y2[i][j];
	//   }
	// }
	//
	// Here we traverse 'j' in 0..H-1 and map r -> j = H-1-r so that the
	// recurrence is evaluated in the correct reverse order while using a
	// Noarr traverser in the forward direction.
	// Again, rows are independent and processed in parallel.
	// ------------------------------------------------------------------

	auto trav_rows_2 = traverser(y2, imgIn).order(hoist<'i'>());

#pragma omp parallel for schedule(static)
	for (auto inner : trav_rows_2) {
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

		// Base state with only the fixed 'i' index; we will add varying 'j'
		auto base_state = inner.state();

		inner.template for_each<'j'>([&](auto state_j) {
			const std::size_t r_j   = get_index<'j'>(state_j);   // 0 .. H-1
			const std::size_t j_idx = h_len - 1 - r_j;           // H-1 .. 0

			// rev_state corresponds to (i, H-1-r_j)
			auto rev_state = base_state + idx<'j'>(j_idx);

			const num_t y2_val = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
			y2[rev_state] = y2_val;

			xp2 = xp1;
			xp1 = imgIn[rev_state];
			yp2 = yp1;
			yp1 = y2_val;
		});
	}

	// ------------------------------------------------------------------
	// Combine vertical passes:
	// imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	// Independent per-element; we parallelize over rows.
	// ------------------------------------------------------------------

	auto trav_vert_combine = traverser(imgOut, y1, y2).order(hoist<'i'>());

#pragma omp parallel for schedule(static)
	for (auto inner : trav_vert_combine) {
		inner.for_each([&](auto state) {
			imgOut[state] = c1 * (y1[state] + y2[state]);
		});
	}

	// ------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//
	// Original C:
	// for (j=0; j<H; j++) {
	//   tm1=0; ym1=0; ym2=0;
	//   for (i=0; i<W; i++) {
	//     y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2;
	//     tm1 = imgOut[i][j];
	//     ym2 = ym1;
	//     ym1 = y1[i][j];
	//   }
	// }
	//
	// Columns (dimension 'j') are independent, so we hoist 'j' and
	// parallelize across columns. Each inner recurrence over 'i' stays
	// sequential.
	// ------------------------------------------------------------------

	auto trav_cols_3 = traverser(y1, imgOut).order(hoist<'j'>());

#pragma omp parallel for schedule(static)
	for (auto inner : trav_cols_3) {
		num_t tm1 = SCALAR_VAL(0.0);
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);

		inner.template for_each<'i'>([&](auto state) {
			const num_t out_val = imgOut[state];
			const num_t y1_val  = a5 * out_val + a6 * tm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y1_val;

			tm1 = out_val;
			ym2 = ym1;
			ym1 = y1_val;
		});
	}

	// ------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	//
	// Original C:
	// for (j=0; j<H; j++) {
	//   tp1=0; tp2=0; yp1=0; yp2=0;
	//   for (i=W-1; i>=0; i--) {
	//     y2[i][j] = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2;
	//     tp2 = tp1; tp1 = imgOut[i][j];
	//     yp2 = yp1; yp1 = y2[i][j];
	//   }
	// }
	//
	// As in the 2nd pass, we traverse 'i' in 0..W-1 and map r -> i = W-1-r,
	// preserving the original reverse-order recurrence while using a
	// Noarr-based forward traversal. Columns are processed in parallel.
	// ------------------------------------------------------------------

	auto trav_cols_4 = traverser(y2, imgOut).order(hoist<'j'>());

#pragma omp parallel for schedule(static)
	for (auto inner : trav_cols_4) {
		num_t tp1 = SCALAR_VAL(0.0);
		num_t tp2 = SCALAR_VAL(0.0);
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);

		// Base state with only the fixed 'j' index; we will add varying 'i'
		auto base_state = inner.state();

		inner.template for_each<'i'>([&](auto state_i) {
			const std::size_t r_i   = get_index<'i'>(state_i);   // 0 .. W-1
			const std::size_t i_idx = w_len - 1 - r_i;           // W-1 .. 0

			// rev_state corresponds to (W-1-r_i, j)
			auto rev_state = base_state + idx<'i'>(i_idx);

			const num_t y2_val = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
			y2[rev_state] = y2_val;

			tp2 = tp1;
			tp1 = imgOut[rev_state];
			yp2 = yp1;
			yp1 = y2_val;
		});
	}

	// ------------------------------------------------------------------
	// Final combine:
	// imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	// Independent per-element; again parallelize over rows.
	// ------------------------------------------------------------------

	auto trav_final = traverser(imgOut, y1, y2).order(hoist<'i'>());

#pragma omp parallel for schedule(static)
	for (auto inner : trav_final) {
		inner.for_each([&](auto state) {
			imgOut[state] = c2 * (y1[state] + y2[state]);
		});
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

